/**
 * Built-in sound library. Audio files are original, royalty-free tracks generated by
 * scripts/generate-sounds.mjs and served from /sounds (long-lived cache, see vercel.json).
 * The Firestore `sounds` collection is seeded from this list (use counts live there).
 */
export interface SoundInfo {
  id: string;
  name: string;
  artist: string;
  audioUrl: string;
  category: string;
  trending: boolean;
  kind: 'music' | 'effect' | 'original';
  useCount?: number;
}

const music = (id: string, file: string, name: string, category: string): SoundInfo =>
  ({ id, name, artist: 'EChat Studio', audioUrl: `/sounds/music/${file}.wav`, category, trending: true, kind: 'music' });
const effect = (id: string, file: string, name: string): SoundInfo =>
  ({ id, name, artist: 'EChat Effects', audioUrl: `/sounds/sfx/${file}.wav`, category: 'Effect', trending: false, kind: 'effect' });

